import numpy as np

# 두 점 A, B. depth map은 각 점의 카메라까지 거리(m)를 안다.
depth = {"A": 1.2, "B": 3.8}  # depth network가 내놓는 표상

def closer_by_depth(depth):
    # 지각(perceive): 기하를 직접 비교 -> 자명하게 결정적
    a, b = depth["A"], depth["B"]
    return "A" if a < b else "B", abs(a - b)

# semantic embedding: CLIP류 token은 '의미'만 부호화한다.
# A=빨간 컵, B=파란 컵. 둘 다 '컵'이라 의미상 거의 동일.
emb = {
    "A":     np.array([0.90, 0.10, 0.05]),  # cup-ness 강함
    "B":     np.array([0.88, 0.12, 0.04]),  # cup-ness 강함
    "query_closer": np.array([0.02, 0.03, 0.99]),  # '더 가까운' = 기하 개념
}

def cos(u, v):
    return float(u @ v / (np.linalg.norm(u) * np.linalg.norm(v)))

def closer_by_semantics(emb):
    # 의미(see): 'closer' 질의와의 유사도로 답을 근사하려 시도
    sa = cos(emb["A"], emb["query_closer"])
    sb = cos(emb["B"], emb["query_closer"])
    winner = "A" if sa > sb else "B"
    return winner, abs(sa - sb)

winner_d, margin_d = closer_by_depth(depth)
winner_s, margin_s = closer_by_semantics(emb)

print(f"[perceive/depth ] closer={winner_d}, margin={margin_d:.2f} (결정적)")
print(f"[see/semantics  ] closer={winner_s}, margin={margin_s:.3f} (근거 없음, 사실상 무작위)")

import numpy as np

# 물체들의 world-frame 위치 (탁자 위 평면, x=오른쪽, y=앞)
world = {
    "cup":   np.array([-0.6,  0.4]),
    "phone": np.array([ 0.7,  0.3]),
    "book":  np.array([ 0.1, -0.5]),
}
# 카메라(나)는 world 원점에서 +y를 바라본다 (egocentric = world와 정렬)
cam_pos, cam_yaw = np.array([0.0, 0.0]), 0.0
# 맞은편 사람: 탁자 반대편에서 나를 마주본다 -> +y 위쪽, yaw=180deg
other_pos, other_yaw = np.array([0.0, 1.2]), 180.0

def rot(deg):
    t = np.radians(deg); c, s = np.cos(t), np.sin(t)
    return np.array([[c, -s], [s, c]])

def to_view(p_world, view_pos, view_yaw):
    # p_view = R(yaw)^T (p_world - t) : world -> viewpoint local frame
    return rot(view_yaw).T @ (p_world - view_pos)

def side(p_view):
    # local x>0 -> 관찰자의 오른쪽, x<0 -> 왼쪽
    return "RIGHT" if p_view[0] > 0 else "LEFT"

print("target  | my(ego) | their(allo)")
for name, p in world.items():
    ego  = to_view(p, cam_pos, cam_yaw)
    allo = to_view(p, other_pos, other_yaw)
    flip = " <== FLIPS" if side(ego) != side(allo) else ""
    print(f"{name:7s} | {side(ego):5s}   | {side(allo):5s}{flip}")
